#include "coin_reference_support.hpp"
#include <iomanip>
using namespace coin_reference;
namespace {
struct Birth {uint64_t id=0,physics=0,idle=0;CoinSnapshot state;};
CoinServices prepared(const CoinsData&d,SessionSnapshot&session,SourceRandom&random){auto s=services(d,session,random);s.owners.clear();s.factories.insert(41);s.next_owner=100;s.parents.emplace(d.assets()[5],CoinParent{71,91,{},{1,1},0});return s;}
void negatives(std::shared_ptr<CoinsData>data,const char*path){
 label="factory negative";SessionSnapshot session;session.cash=43;SourceRandom random(1);auto s=prepared(*data,session,random);CoinFactory factory;const auto original=random.state();const auto nan=std::numeric_limits<float>::quiet_NaN();
 CHECK(!factory.prepare(nullptr,71,41,{},s,error));CHECK(!factory.prepare(data,71,41,{nan,0},s,error));CHECK(!factory.valid()&&random.state()==original);
 for(unsigned k=0;k<13;++k){auto bad=s;if(k==0)bad.epoch=72;if(k==1)bad.factories.clear();if(k==2)bad.parents.clear();if(k==3)bad.parents.begin()->second.token=0;if(k==4)bad.parents.begin()->second.epoch=72;if(k==5)bad.parents.begin()->second.position.x=1;if(k==6)bad.parents.begin()->second.scale.x=2;if(k==7)bad.parents.begin()->second.rotation=1;if(k==8)bad.hud_ready=false;if(k==9)bad.sounds.clear();if(k==10)bad.random=nullptr;if(k==11)bad.next_owner=0;if(k==12)bad.next_owner=UINT64_MAX;CHECK(!factory.prepare(data,71,41,{},bad,error));CHECK(!factory.valid()&&random.state()==original&&session.cash==43);}
 CHECK(factory.prepare(data,71,41,{3,7},s,error));CHECK(!factory.spawn(71,0,s,error));CHECK(!factory.spawn(71,UINT32_MAX,s,error));CHECK(!factory.set_position(71,{nan,0},s,error));CHECK(factory.position().x==3&&factory.position().y==7&&factory.timer()==0&&!factory.spawning());CHECK(factory.spawn(71,2,s,error));
 s.physics_step=1;s.frame=1;CHECK(factory.advance_physics(71,s,error));CHECK(factory.instances().empty()&&factory.timer()==double(data->policy().delta)&&random.state()==original);CHECK(!factory.advance_physics(71,s,error));
 const auto elapsed=factory.timer();s.physics_step=2;s.frame=2;for(uint64_t id=1000;id<5096;++id)s.owners.insert(id);CHECK(!factory.advance_physics(71,s,error));CHECK(factory.instances().empty()&&factory.remaining()==2&&factory.timer()==elapsed&&random.state()==original&&s.next_owner==100);s.owners.clear();
 auto bad=s;bad.parents.begin()->second.token=92;CHECK(!factory.advance_physics(71,bad,error));CHECK(factory.instances().empty()&&factory.timer()==elapsed&&random.state()==original);CHECK(factory.advance_physics(71,s,error));CHECK(factory.instances().size()==1&&factory.remaining()==1&&s.next_owner==101&&s.last_assigned_owner==100);auto*retained=factory.actor(100);CHECK(retained&&s.owners.count(100));
 const auto first_state=fingerprint(*retained);const auto rng=random.state();bad=s;bad.next_owner=100;CHECK(!factory.advance_physics(71,bad,error));CHECK(factory.actor(100)==retained&&fingerprint(*retained)==first_state&&random.state()==rng);bad=s;bad.owners.erase(100);CHECK(!factory.spawn(71,1,bad,error));CHECK(factory.actor(100)==retained&&random.state()==rng);CHECK(!factory.prepare(data,71,41,{},s,error));
 s.physics_step=3;s.frame=3;CHECK(factory.advance_physics(71,s,error));CHECK(factory.instances().size()==2&&factory.actor(100)==retained&&!factory.spawning()&&factory.remaining()==0);CHECK(!factory.spawn_default(71,s,error));CHECK(factory.set_position(71,{-5,9},s,error));CHECK(factory.spawn(71,1,s,error));s.physics_step=4;s.frame=4;CHECK(factory.advance_physics(71,s,error));CHECK(factory.actor(102)&&factory.actor(102)->snapshot().position.x==-5&&factory.actor(100)==retained);
 // Pending child commands must drain before scene retirement; unrelated
 // registry identities remain owned by their own scene consumers.
 s.bodies[1]=CoinBodyKind::PartyObject;CHECK(retained->body_entered(71,1,s,error));const auto cash=session.cash;CHECK(!factory.leave(71,s,error));CHECK(factory.instances().size()==3&&session.cash==cash);s.requests.clear();s.owners.insert(999);CHECK(factory.leave(71,s,error));CHECK(!factory.valid()&&factory.instances().empty()&&s.owners==std::set<uint64_t>{999}&&!s.factories.count(41));CHECK(!factory.spawn(71,1,s,error));
 auto current=prepared(*data,session,random);CoinFactory stale;CHECK(stale.prepare(data,71,41,{},current,error));const auto generation=data->generation();CHECK(data->load_file(path,error));CHECK(data->generation()==generation+1);const auto unchanged=random.state();CHECK(!stale.spawn(71,1,current,error));CHECK(stale.instances().empty()&&random.state()==unchanged);
}
}
int main(int argc,char**argv){
 CHECK(argc==3);auto data=std::make_shared<CoinsData>();CHECK(data->load_file(argv[1],error));std::ifstream in(argv[2]);CHECK(read<std::string>(in)=="ENCCOIN_FACTORY04");const auto count=read<unsigned>(in);CHECK(count>0&&count<=64);
 for(unsigned ci=0;ci<count;++ci){CHECK(read<unsigned>(in)==ci);const auto name=read<std::string>(in);label=name;const auto seed=read<uint64_t>(in);const auto use_default=read<unsigned>(in),amount=read<unsigned>(in),restart_frame=read<unsigned>(in),restart_amount=read<unsigned>(in);const auto position=point(in);const auto frames=read<unsigned>(in);CHECK(frames>0&&frames<=10000);
  SessionSnapshot session;session.cash=29;session.storage.resize(3);const auto*storage=session.storage.data();SourceRandom random(seed);auto s=services(*data,session,random);s.owners.clear();s.factories.insert(41);s.next_owner=100;s.parents.emplace(data->assets()[5],CoinParent{71,91,{},{1,1},0});CircleMotionSolver solver;CHECK(solver.configure(data->policy().body_radius,{},data->policy().margin,{}));CoinFactory factory;CHECK(factory.prepare(data,71,41,position,s,error));if(use_default)CHECK(factory.spawn_default(71,s,error));else CHECK(factory.spawn(71,amount,s,error));std::vector<Birth>births;
  for(unsigned frame=0;frame<frames;++frame){label=name+':'+std::to_string(frame);
   if(frame){s.frame=frame-1;std::vector<uint64_t>existing;for(const auto&entry:factory.instances())existing.push_back(entry.first);for(auto id:existing){auto*actor=factory.actor(id);CHECK(actor&&actor->advance_idle(71,data->policy().delta,s,error));CHECK(actor->flush_deferred(71,s,error));}
    s.frame=frame;s.physics_step=frame;for(auto id:existing){auto*actor=factory.actor(id);CHECK(actor->advance_physics(71,solver,s,error));CHECK(actor->flush_deferred(71,s,error));}
    const auto before=factory.instances().size();CoinActor*retained=births.empty()?nullptr:factory.actor(births[0].id);CHECK(factory.advance_physics(71,s,error));CHECK(factory.instances().size()==before||factory.instances().size()==before+1);if(retained)CHECK(retained==factory.actor(births[0].id));if(factory.instances().size()>before){const auto id=s.next_owner-1;CHECK(factory.actor(id));births.push_back({id,s.physics_step,s.frame,factory.actor(id)->snapshot()});}
    for(const auto&entry:factory.instances())CHECK(factory.actor(entry.first)->flush_deferred(71,s,error));
   }
   if(frame&&frame==restart_frame)CHECK(factory.spawn(71,restart_amount,s,error));
   CHECK(read<unsigned>(in)==frame);CHECK(bits(factory.timer())==read<uint64_t>(in));CHECK(factory.spawning()==bool(read<unsigned>(in)));CHECK(factory.remaining()==read<uint32_t>(in));CHECK(session.cash==read<int64_t>(in));CHECK(session.storage.data()==storage&&session.storage.size()==3);CHECK(read<unsigned>(in)==0&&read<unsigned>(in)==0&&s.requests.empty());
   CHECK(births.size()==read<unsigned>(in));for(size_t n=0;n<births.size();++n){const auto&birth=births[n];CHECK(read<size_t>(in)==n);CHECK(birth.physics==read<uint64_t>(in));CHECK(birth.idle==read<uint64_t>(in));std::string parent;in>>std::quoted(parent);CHECK(parent==data->assets()[5]);point(in,birth.state.position);CHECK(bits(birth.state.speed)==read<uint64_t>(in));point(in,birth.state.direction);CHECK(bits(birth.state.air_time)==read<uint64_t>(in));CHECK(birth.state.sparkle==read<uint32_t>(in));}
   CHECK(factory.instances().size()==read<unsigned>(in));size_t ordinal=0;for(const auto&entry:factory.instances()){CHECK(read<size_t>(in)==ordinal++);CHECK(s.owners.count(entry.first));state(in,entry.second,0);}
  }
  CHECK(read<std::string>(in)=="TAIL");CHECK(random.randi()==read<uint32_t>(in));CHECK(factory.leave(71,s,error));CHECK(!factory.valid()&&factory.instances().empty()&&s.owners.empty());
 }
 in>>std::ws;CHECK(in.peek()==std::char_traits<char>::eof());negatives(data,argv[1]);std::cout<<checks<<" Coin factory and child source checks passed\n";
}
